export type ParsedActivateLiquidityInstruction<
  TProgram extends string = typeof CLEARING_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    authority: TAccountMetas[0];
    venue: TAccountMetas[1];
    custody: TAccountMetas[2];
    safety: TAccountMetas[3];
    btc: TAccountMetas[4];
    eth: TAccountMetas[5];
    btcLedger: TAccountMetas[6];
    ethLedger: TAccountMetas[7];
    vault: TAccountMetas[8];
    eventAuthority: TAccountMetas[9];
    program: TAccountMetas[10];
    resolution: TAccountMetas[11];
  };
  data: ActivateLiquidityInstructionData;
};

export function parseActivateLiquidityInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedActivateLiquidityInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 12) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 12,
      },
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      authority: getNextAccount(),
      venue: getNextAccount(),
      custody: getNextAccount(),
      safety: getNextAccount(),
      btc: getNextAccount(),
      eth: getNextAccount(),
      btcLedger: getNextAccount(),
      ethLedger: getNextAccount(),
      vault: getNextAccount(),
      eventAuthority: getNextAccount(),
      program: getNextAccount(),
      resolution: getNextAccount(),
    },
    data: getActivateLiquidityInstructionDataDecoder().decode(instruction.data),
  };
}
